import{_ as t,o as e,c as o,a5 as p}from"./chunks/framework.Cooo9kuv.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"IM012-批量为文件夹内图片添加黑色边框","日期":"2026-04-12T00:00:00.000Z","修改日期":"2026-04-12T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["图片批处理"],"标签":["图片添加边框","批量为图片添加边框","批量添加图片边框","添加图片边框"]},"headers":[],"relativePath":"md/图片批处理/IM012-批量为文件夹内图片添加黑色边框.md","filePath":"md/图片批处理/IM012-批量为文件夹内图片添加黑色边框.md"}'),n={name:"md/图片批处理/IM012-批量为文件夹内图片添加黑色边框.md"};function r(s,a,_,m,c,g){return e(),o("div",null,[...a[0]||(a[0]=[p('<p>批量为图片添加黑色边框</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250224165019174038701924323.png" alt=""></p><h3 id="程序说明" tabindex="-1">程序说明 <a class="header-anchor" href="#程序说明" aria-label="Permalink to &quot;程序说明&quot;">​</a></h3><p>比如A文件夹下有K、H、G....等文件夹，文件夹下都有一定的图片，将程序放在A文件夹下，运行后会为K、H、G....等文件夹下图片添加黑色边框，</p><p>如下图所示，会自动创建一个新的文件夹（原文件夹名-添加黑框后）将添加黑框后的图片放在该文件夹内。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250224165546174038734675181.png" alt=""></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250224165041174038704198652.png" alt=""></p><h3 id="imagemagick安装方式" tabindex="-1">ImageMagick安装方式 <a class="header-anchor" href="#imagemagick安装方式" aria-label="Permalink to &quot;ImageMagick安装方式&quot;">​</a></h3><p>先在电脑D盘创建文件夹：ImageMagick  然后将其安装在这个文件夹内</p><p>如果电脑没有D盘则在C盘按照此方式创建文件夹安装</p><p>如果你是win32位操作系统则使用32位的程序（X86）安装，如果是64位操作系统则按照64位的程序（X64）安装</p><p><strong>ImageMagick下载：</strong></p><p>通过网盘分享的文件：ImageMagick安装（必须安装此工具）<br> 链接: <a href="https://pan.baidu.com/s/12cRu46eo0m0xOFZP_aLt2A?pwd=myti" target="_blank" rel="noreferrer">https://pan.baidu.com/s/12cRu46eo0m0xOFZP_aLt2A?pwd=myti</a> 提取码: myti</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/1503.html" target="_blank" rel="noreferrer">https://www.softbangong.com/1503.html</a></p>',15)])])}const d=t(n,[["render",r]]);export{l as __pageData,d as default};
